<?php
require_once __DIR__ . '/tienda_helpers.php';
require_once __DIR__ . '/email_service.php';
$ctx=require_customer();$user=$ctx['usuario'];$clienteId=$ctx['cliente_id'];$pdo=db();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Método no permitido.'],405);$d=body_json();$id=(int)($d['pedido_id']??0);if(!$id)json_response(['error'=>'Pedido inválido.'],422);
$st=$pdo->prepare("SELECT id,folio,subtotal,descuento_monto,impuesto_porcentaje,impuesto_monto,total,metodo_pago FROM erp_ordenes WHERE id=? AND cliente_id=? AND usuario_cliente_id=? AND origen='tienda' LIMIT 1");$st->execute([$id,$clienteId,$user['id']]);$order=$st->fetch();if(!$order)json_response(['error'=>'Pedido no encontrado.'],404);
$st=$pdo->prepare('SELECT d.cantidad,d.subtotal,p.nombre FROM erp_orden_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.orden_id=?');$st->execute([$id]);$items=$st->fetchAll();$sent=tienda_enviar_recibo($user['correo'],$user['nombre'],['folio'=>$order['folio'],'productos'=>$items,'subtotal'=>$order['subtotal'],'descuento_monto'=>$order['descuento_monto'],'impuesto_porcentaje'=>$order['impuesto_porcentaje'],'impuesto_monto'=>$order['impuesto_monto'],'total'=>$order['total'],'metodo_pago'=>$order['metodo_pago']]);$state=$sent['sent']?'enviado':'pendiente_configuracion';$pdo->prepare('UPDATE erp_ordenes SET correo_recibo_estado=? WHERE id=?')->execute([$state,$id]);if(!$sent['sent'])json_response(['error'=>$sent['reason']==='smtp_not_configured'?'El servicio SMTP aún no está configurado.':'No fue posible enviar el correo. Revisa la configuración SMTP.'],503);json_response(['ok'=>true,'mensaje'=>'Recibo enviado nuevamente al correo de tu cuenta.']);
